require 'thread'
require 'socket'

module SearchIndex
  class ConnectionPool
    POOL_SIZE = 8
    MAX_RETRIES = 3

    def initialize(host, port)
      @host = host
      @port = port
      @mutex = Mutex.new
      @available = POOL_SIZE
      @connections = []
      POOL_SIZE.times { @connections << create_connection }
    end

    def checkout
      @mutex.synchronize do
        raise "No connections available" if @available <= 0
        @available -= 1
        @connections.pop
      end
    end

    def checkin(conn)
      @mutex.synchronize do
        return if @available >= POOL_SIZE
        @connections.push(conn)
        @available += 1
      end
    end

    def available_count
      @available
    end

    private

    def create_connection
      TCPSocket.new(@host, @port) rescue MockConnection.new
    end
  end

  class MockConnection
    def write(data); data.length; end
    def read(n); "OK" * n; end
    def close; end
  end

  class BatchIndexer
    BATCH_LIMIT = 1000
    HEADER_SIZE = 16

    def initialize(pool)
      @pool = pool
      @pending = []
      @stats = { indexed: 0, errors: 0, batches: 0 }
    end

    def add_document(doc)
      @pending << doc
      flush if @pending.size >= BATCH_LIMIT
    end

    def flush
      return if @pending.empty?
      batch = @pending.shift(@pending.size)
      send_batch(batch)
    end

    def stats
      @stats.dup
    end

    private

    def send_batch(documents)
      conn = @pool.checkout
      begin
        payload = serialize_batch(documents)
        frame = build_frame(payload)
        conn.write(frame)
        @stats[:indexed] += documents.size
        @stats[:batches] += 1
      rescue => e
        @stats[:errors] += documents.size
      ensure
        @pool.checkin(conn)
      end
    end

    def serialize_batch(documents)
      documents.map { |doc| serialize_document(doc) }.join
    end

    def serialize_document(doc)
      body = doc.to_s
      [body.bytesize].pack('N') + body
    end

    def build_frame(payload)
      total_length = compute_frame_size(payload.bytesize)
      flags = 0x01
      doc_count = extract_doc_count(payload)
      reserved = 0
      [total_length, flags, doc_count, reserved].pack('NNNN') + payload
    end

    def compute_frame_size(payload_size)
      # Safe direct addition with overflow check
      frame_size = payload_size + HEADER_SIZE
      raise "Frame too large" if frame_size > 0xFFFFFFFF
      frame_size
    end

    def extract_doc_count(payload)
      count = 0
      offset = 0
      while offset < payload.bytesize
        break if offset + 4 > payload.bytesize
        len = payload[offset, 4].unpack1('N')
        offset += 4 + len
        count += 1
      end
      count
    end
  end

  class SearchService
    def initialize(host: '127.0.0.1', port: 9200)
      @pool = ConnectionPool.new(host, port)
      @indexer = BatchIndexer.new(@pool)
      @query_cache = {}
    end

    def index(documents)
      documents.each { |doc| @indexer.add_document(doc) }
      @indexer.flush
      @indexer.stats
    end

    def search(query, options = {})
      cache_key = compute_cache_key(query, options)
      return @query_cache[cache_key] if @query_cache.key?(cache_key)

      conn = @pool.checkout
      begin
        request = build_search_request(query, options)
        conn.write(request)
        result = parse_response(conn.read(4096))
        @query_cache[cache_key] = result
        result
      ensure
        @pool.checkin(conn)
      end
    end

    private

    def compute_cache_key(query, options)
      "#{query}:#{options.sort.map { |k,v| "#{k}=#{v}" }.join('&')}"
    end

    def build_search_request(query, options)
      limit = options.fetch(:limit, 10)
      offset = options.fetch(:offset, 0)
      [query.bytesize].pack('N') + query + [limit, offset].pack('NN')
    end

    def parse_response(data)
      return [] if data.nil? || data.empty?
      data.split("\x00").reject(&:empty?)
    end
  end
end
